sys_ws_operation.operation_script:
// Scripted REST: POST /api/x_1821654_governa/ledger/runs/{run_id}/actions
// v0.3 §4.3（2026-09-20 G）:
//   * 確定済みの run には追記できない（409）。create-only 台帳の不変性
//   * 同じ run の同じ sequence は重複させない（409）。reconcile の 1 action = 1 事象の前提
//   * policy 参照・policy_content_hash・instance_outcome・enforcing_artifact・pre_state_hash を受け取る
//   * policy_rule_hash は廃止（sys_id 文字列のハッシュで意味がなかった）。受け取っても書かない
(function process(request, response) {
    var runId = request.pathParams.run_id;
    var run = new GlideRecord('x_1821654_governa_run');
    if (!run.get(runId)) { response.setStatus(404); return { error: 'run not found' }; }
    if (run.getValue('outcome')) { response.setStatus(409); return { error: 'run already finalized' }; }

    var OUTCOMES = ['not_attempted', 'applied', 'aborted_by_rule', 'denied_by_acl',
                    'denied_by_data_policy', 'error', 'unknown'];
    var items = (request.body.data && request.body.data.actions) || [];

    // 先に全件を検査してから書く（途中まで書いて失敗するのを避ける）
    var seen = {};
    for (var j = 0; j < items.length; j++) {
        var s = String(items[j].sequence);
        var io = items[j].instance_outcome || 'not_attempted';
        if (seen[s]) { response.setStatus(409); return { error: 'duplicate sequence in request: ' + s }; }
        seen[s] = true;
        if (OUTCOMES.indexOf(io) < 0) { response.setStatus(400); return { error: 'unknown instance_outcome: ' + io }; }
        var dup = new GlideRecord('x_1821654_governa_action');
        dup.addQuery('run', runId);
        dup.addQuery('sequence', items[j].sequence);
        dup.setLimit(1);
        dup.query();
        if (dup.hasNext()) { response.setStatus(409); return { error: 'sequence already recorded: ' + s }; }
    }

    var ids = [];
    for (var i = 0; i < items.length; i++) {
        var a = items[i];
        var gr = new GlideRecord('x_1821654_governa_action');
        gr.initialize();
        gr.setValue('run', runId);
        gr.setValue('sequence', a.sequence);
        gr.setValue('tool', a.tool);
        gr.setValue('target_table', a.target_table || '');
        gr.setValue('target_sys_id', a.target_sys_id || '');
        gr.setValue('params_hash', a.params_hash || '');
        gr.setValue('policy_decision', a.policy_decision || 'allow');
        gr.setValue('executed', a.executed === true);
        gr.setValue('occurred_at', a.occurred_at);
        if (a.latency_ms !== undefined) gr.setValue('latency_ms', a.latency_ms);
        if (a.policy) gr.setValue('policy', a.policy);
        if (a.policy_version) gr.setValue('policy_version', a.policy_version);
        if (a.policy_content_hash) gr.setValue('policy_content_hash', a.policy_content_hash);
        if (a.matched_policies) gr.setValue('matched_policies', a.matched_policies);
        if (a.deny_reason) gr.setValue('deny_reason', a.deny_reason);
        gr.setValue('instance_outcome', a.instance_outcome || 'not_attempted');
        if (a.enforcing_artifact) gr.setValue('enforcing_artifact', a.enforcing_artifact);
        if (a.pre_state_hash) gr.setValue('pre_state_hash', a.pre_state_hash);
        ids.push(gr.insert());
    }
    response.setStatus(201);
    return { inserted: ids.length, sys_ids: ids };
})(request, response);
